-- TripNest upgrade 3: hotel details motham database lo (11 kotha tables). OKKA SARI matrame run cheyandi.
USE tripnest;

ALTER TABLE hotels
  ADD COLUMN location VARCHAR(150), ADD COLUMN address VARCHAR(255), ADD COLUMN description TEXT,
  ADD COLUMN latitude DECIMAL(9,6), ADD COLUMN longitude DECIMAL(9,6),
  ADD COLUMN video_url VARCHAR(500), ADD COLUMN panorama_url VARCHAR(500);

-- sample reviews ki user lekunda reviewer_name pettadam kosam
ALTER TABLE reviews MODIFY user_id INT NULL, ADD COLUMN reviewer_name VARCHAR(100), ADD COLUMN helpful INT NOT NULL DEFAULT 0;

CREATE TABLE hotel_images (image_id INT AUTO_INCREMENT PRIMARY KEY, hotel_id INT NOT NULL, url VARCHAR(500) NOT NULL, sort_order INT NOT NULL DEFAULT 0,
  FOREIGN KEY (hotel_id) REFERENCES hotels(hotel_id) ON DELETE CASCADE);
CREATE TABLE hotel_badges (hotel_id INT NOT NULL, badge VARCHAR(40) NOT NULL, sort_order INT NOT NULL DEFAULT 0, PRIMARY KEY (hotel_id, badge),
  FOREIGN KEY (hotel_id) REFERENCES hotels(hotel_id) ON DELETE CASCADE);
CREATE TABLE amenities (amenity_id INT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(30) NOT NULL, label VARCHAR(60) NOT NULL UNIQUE);
CREATE TABLE hotel_amenities (hotel_id INT NOT NULL, amenity_id INT NOT NULL, sort_order INT NOT NULL DEFAULT 0, PRIMARY KEY (hotel_id, amenity_id),
  FOREIGN KEY (hotel_id) REFERENCES hotels(hotel_id) ON DELETE CASCADE, FOREIGN KEY (amenity_id) REFERENCES amenities(amenity_id) ON DELETE CASCADE);
CREATE TABLE rooms (room_id INT PRIMARY KEY, hotel_id INT NOT NULL, name VARCHAR(100) NOT NULL, size_label VARCHAR(20), capacity_label VARCHAR(30), bed VARCHAR(60),
  price DECIMAL(10,2) NOT NULL, cancellation VARCHAR(120), sort_order INT NOT NULL DEFAULT 0,
  FOREIGN KEY (hotel_id) REFERENCES hotels(hotel_id) ON DELETE CASCADE);
CREATE TABLE room_features (room_id INT NOT NULL, feature VARCHAR(60) NOT NULL, sort_order INT NOT NULL DEFAULT 0, PRIMARY KEY (room_id, feature),
  FOREIGN KEY (room_id) REFERENCES rooms(room_id) ON DELETE CASCADE);
CREATE TABLE room_images (image_id INT AUTO_INCREMENT PRIMARY KEY, room_id INT NOT NULL, url VARCHAR(500) NOT NULL, sort_order INT NOT NULL DEFAULT 0,
  FOREIGN KEY (room_id) REFERENCES rooms(room_id) ON DELETE CASCADE);
CREATE TABLE hotel_policies (policy_id INT AUTO_INCREMENT PRIMARY KEY, hotel_id INT NOT NULL, label VARCHAR(40) NOT NULL, policy_value VARCHAR(80) NOT NULL, sort_order INT NOT NULL DEFAULT 0,
  FOREIGN KEY (hotel_id) REFERENCES hotels(hotel_id) ON DELETE CASCADE);
CREATE TABLE hotel_rules (rule_id INT AUTO_INCREMENT PRIMARY KEY, hotel_id INT NOT NULL, rule_text VARCHAR(200) NOT NULL, sort_order INT NOT NULL DEFAULT 0,
  FOREIGN KEY (hotel_id) REFERENCES hotels(hotel_id) ON DELETE CASCADE);
CREATE TABLE hotel_attractions (attraction_id INT AUTO_INCREMENT PRIMARY KEY, hotel_id INT NOT NULL, icon VARCHAR(30) NOT NULL, name VARCHAR(100) NOT NULL, distance VARCHAR(30) NOT NULL, sort_order INT NOT NULL DEFAULT 0,
  FOREIGN KEY (hotel_id) REFERENCES hotels(hotel_id) ON DELETE CASCADE);
CREATE TABLE hotel_faqs (faq_id INT AUTO_INCREMENT PRIMARY KEY, hotel_id INT NOT NULL, question VARCHAR(200) NOT NULL, answer TEXT NOT NULL, sort_order INT NOT NULL DEFAULT 0,
  FOREIGN KEY (hotel_id) REFERENCES hotels(hotel_id) ON DELETE CASCADE);


-- ===== Hotel 1: Azure Cliff Resort =====
UPDATE hotels SET location = 'Oia, Santorini, Greece', address = 'Oia, Santorini, Greece — guest entrance on main road', description = 'Azure Cliff Resort offers a memorable stay in Oia, Santorini, Greece, with comfortable rooms, friendly service and easy access to the best local sights.', latitude = 36.4618, longitude = 25.3753, video_url = 'https://interactive-examples.mdn.mozilla.net/media/cc0-videos/flower.mp4', panorama_url = 'https://images.unsplash.com/photo-1570077188670-e3a8d69ac5ff?auto=format&fit=crop&w=2400&q=80' WHERE hotel_id = 1;

