SELECT h.name, (SELECT COUNT(*) FROM rooms r WHERE r.hotel_id = h.hotel_id) AS rooms, (SELECT COUNT(*) FROM hotel_images i WHERE i.hotel_id = h.hotel_id) AS images FROM hotels h;
